Here is the commit message:
polarssl: fixed compile errors introduced in 6448f98c

Here is the root cause:
The bug was likely caused by incorrect parameter naming in the `polarssl_version_from_curl` function, which could lead to confusion and potential misuse of the function, as well as a mismatch in the expected parameter type in the function declaration of `set_ssl_version_min_max`, which may have caused compile errors.

Here is the patch:

-static CURLcode polarssl_version_from_curl(int *polarver, long version)
+static CURLcode polarssl_version_from_curl(int *polarver, long ssl_version)
 {
   switch(ssl_version) {
     case CURL_SSLVERSION_TLSv1_0:
       *polarver = SSL_MINOR_VERSION_1;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_1:
       *polarver = SSL_MINOR_VERSION_2;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_2:
       *polarver = SSL_MINOR_VERSION_3;
       return CURLE_OK;
     case CURL_SSLVERSION_TLSv1_3:
       break;
   }
   return CURLE_SSL_CONNECT_ERROR;
 }

 static CURLcode
-set_ssl_version_min_max(struct connectdata *conn, int sockindex);
+set_ssl_version_min_max(struct connectdata *conn, int sockindex)
 {
   struct Curl_easy *data = conn->data;
   struct ssl_connect_data* connssl = &conn->ssl[sockindex];
   long ssl_version = SSL_CONN_CONFIG(version);
   long ssl_version_max = SSL_CONN_CONFIG(version_max);
   int ssl_min_ver = SSL_MINOR_VERSION_1;
   int ssl_max_ver = SSL_MINOR_VERSION_1;
   CURLcode result = CURLE_OK;

   switch(ssl_version) {
     case CURL_SSLVERSION_DEFAULT:
     case CURL_SSLVERSION_TLSv1:
       ssl_version = CURL_SSLVERSION_TLSv1_0;
       ssl_version_max = CURL_SSLVERSION_MAX_TLSv1_2;
       break;
   }

   switch(ssl_version_max) {
     case CURL_SSLVERSION_MAX_NONE:
       ssl_version_max = ssl_version << 16;
       break;
     case CURL_SSLVERSION_MAX_DEFAULT:
       ssl_version_max = CURL_SSLVERSION_MAX_TLSv1_2;
       break;
   }

   result = polarssl_version_from_curl(&ssl_min_ver, ssl_version);
   if(result) {
     failf(data, "unsupported min version passed via CURLOPT_SSLVERSION");
     return result;
   }
   result = polarssl_version_from_curl(&ssl_max_ver, ssl_version_max >> 16);
   if(result) {
     failf(data, "unsupported max version passed via CURLOPT_SSLVERSION");
     return result;
   }

   ssl_set_min_version(&connssl->ssl, SSL_MAJOR_VERSION_3, ssl_min_ver);
   ssl_set_max_version(&connssl->ssl, SSL_MAJOR_VERSION_3, ssl_max_ver);

   return result;
 }



